/* oxlint-disable camelcase*/
import * as E from './../../bundled-dependencies/wix-bi-logger-rich-editor.js';
import type { BISettings } from './../../ricos-common/ricos-types.js';
import type { Node } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { BICallbacks, LinkDecoration } from './../../ricos-types/index.js';
import { Node_Type } from './../../ricos-types/index.js';

import type { RicosBILogger } from './ricos-bi-logger.js';

const onPluginActionMap = {
  addPluginLink: E.addPluginLink,
  searchForPlugin: E.searchForPlugin,
  searchInsideThePlugin: E.searchInsideThePlugin,
  pluginTableColumnRowAction: E.pluginTableColumnRowAction,
  tablePluginAddColumnRow: E.tablePluginAddColumnRow,
  tablePluginDeleteColumnRow: E.tablePluginDeleteColumnRow,
  tablePluginClickOnOptionMenu: E.tablePluginClickOnOptionMenu,
  tablePluginClickActionFromOptionMenu: E.tablePluginClickActionFromOptionMenu,
  settingsModalOpenedForPlugin: E.settingsModalOpenedForPlugin,
  settingsModalClosedForPlugin: E.settingsModalClosedForPlugin,
};

type RicosBICallbacksType = (
  biLogger: RicosBILogger,
  params: Pick<BISettings, 'postId'>
) => Required<BICallbacks>;

export const ricosBICallbacks: RicosBICallbacksType = (biLogger, { postId }) => {
  return {
    biLogger,
    onModalAction: ({
      pluginId,
      modalId,
      modalSessionId,
      actionName,
      value,
      actionNumber,
      initialSelection,
      style,
    }) => {
      biLogger.log(modalAction, {
        action: actionName,
        modal_session_id: modalSessionId,
        numActions: actionNumber - 1,
        actionNumber,
        modal_id: modalId,
        plugin_id: pluginId,
        content_id: '',
        uuid: '',
        // @ts-expect-error not yet declared on the event
        value,
        initial_selection: initialSelection,
        style,
      });
    },
    onPluginAdd: (plugin_id, entry_point, version, content_id) =>
      biLogger.log(E.addPlugin, {
        plugin_id,
        search_term: undefined,
        entry_point,
        version,
        content_id,
        entry_type: undefined,
        plugins_details: undefined,
        pluginUniqueId: undefined,
        button_name: undefined,
        plugin_specification: undefined,
        editor_engine: undefined,
      }),
    onPluginAddStep: ({
      entryPoint,
      entryType,
      pluginDetails,
      pluginId,
      step,
      version,
      contentId: content_id,
    }) =>
      biLogger.log(E.addPluginStep, {
        entry_point: entryPoint,
        entry_type: entryType,
        params: undefined,
        plugin_id: pluginId,
        pluginUniqueId: pluginDetails as string,
        plugins_details: undefined,
        step,
        version,
        content_id,
        plugin_specification: undefined,
      }),
    onPluginAddSuccess: (plugin_id, entry_point, params, version, content_id) =>
      biLogger.log(E.addPluginSuccess, {
        plugin_id,
        entry_point,
        entry_type: undefined,
        params: JSON.stringify(params),
        plugins_details: undefined,
        pluginUniqueId: undefined,
        version,
        content_id,
        plugin_specification: undefined,
        editor_engine: undefined,
        is_tiptap: undefined,
        mediaOrigin: undefined,
      }),
    onPluginDelete: ({ pluginId, pluginDetails, version, contentId: content_id }) =>
      biLogger.log(E.deletePlugin, {
        plugin_id: pluginId,
        plugins_details: JSON.stringify(pluginDetails || {}),
        pluginUniqueId: undefined,
        version,
        content_id,
        editor_engine: undefined,
      }),
    onPluginChange: (plugin_id, pluginDetails, version, content_id) =>
      biLogger.log(E.changePlugin, {
        plugin_id,
        plugins_details: JSON.stringify(pluginDetails),
        settingSessionId: undefined,
        button_name: undefined,
        category: undefined,
        origin: undefined,
        type: undefined,
        value: undefined,
        pluginUniqueId: undefined,
        version,
        content_id,
        editor_engine: undefined,
      }),

    onPublish: (post_id, plugins_count, _plugins_details, version, content_id) =>
      biLogger.log(E.publishPost, {
        post_id: post_id || postId,
        plugins_count: plugins_count ? JSON.stringify(plugins_count) : undefined,
        plugins_details: '', // plugins_details && JSON.stringify(_plugins_details),
        params: undefined,
        version,
        content_id,
        editor_engine: undefined,
        is_tiptap: undefined,
      }),
    onMenuLoad: ({ menu, version, contentId: content_id }) =>
      biLogger.log(E.menuLoad, {
        menu,
        version,
        content_id,
      }),
    onPluginModalOpened: ({
      entryPoint,
      entryType,
      pluginDetails,
      pluginId,
      version,
      contentId: content_id,
      dropdownValue,
      modalSessionId,
    }) =>
      biLogger.log(E.pluginModalOpened, {
        entry_point: entryPoint,
        entry_type: entryType,
        plugin_id: pluginId,
        plugins_details: JSON.stringify(pluginDetails),
        version,
        content_id,
        plugin_specification: undefined,
        editor_engine: undefined,
        is_tiptap: undefined,
        dropdown_value: dropdownValue,
        modal_session_id: modalSessionId,
      }),
    onViewerAction: (plugin_id, action_name, value, content_id, partialNode) => {
      biLogger.log(E.viewerAction, {
        action_name,
        plugin_id,
        value,
        plugins_details: undefined,
        pluginUniqueId: undefined,
        content_id,
        params: undefined,
        productType: undefined,
        plugin_specification: undefined,
      });

      const analyticsData = buildAnyButtonClickActionParams(content_id, partialNode);
      if (analyticsData) {
        biLogger.log(analyticsAnyButtonClickAction, analyticsData);
      }
    },

    onViewerLoaded: ({ isPreview, url: postURL, pluginsCount, version, contentId: content_id }) => {
      // Enforcement fix for a boolean `isPreview` value
      const preview =
        typeof isPreview === 'boolean'
          ? isPreview
          : typeof isPreview === 'string' && isPreview === 'true';
      biLogger.log(E.viewerLoaded, {
        preview,
        postURL,
        version,
        content_id,
        pluginsCount: JSON.stringify(pluginsCount),
      });
    },
    onOpenEditorSuccess: (version, toolbarType, content_id) =>
      biLogger.log(E.openEditorSuccess, {
        toolbarType,
        version,
        content_id,
        editor_engine: undefined,
        is_tiptap: undefined,
      }),
    onContentEdited: ({ version, contentId: content_id }) =>
      biLogger.log(E.contentAdded, {
        version,
        content_id,
        contact_id: undefined,
        container_type: undefined,
        editing_time: undefined,
        paragraph_count: undefined,
        word_count: undefined,
        editor_engine: undefined,
        is_tiptap: undefined,
      }),
    onInlineToolbarOpen: ({ version, toolbarType, pluginId, contentId: content_id }) =>
      biLogger.log(E.inlineToolbarOpened, {
        version,
        content_id,
        toolbarType,
        plugin_id: pluginId,
      }),
    onToolbarButtonClick: ({
      buttonName,
      category,
      origin,
      pluginDetails,
      pluginId,
      pluginUniqueId,
      type,
      value,
      version,
      contentId: content_id,
    }) =>
      biLogger.log(E.changePlugin, {
        button_name: buttonName,
        category,
        origin,
        pluginUniqueId,
        plugin_id: pluginId,
        plugins_details: pluginDetails,
        type,
        value,
        version,
        content_id,
        settingSessionId: undefined,
        editor_engine: undefined,
      }),
    onKeyboardShortcutAction: ({ buttonName, pluginId, value, version, contentId: content_id }) =>
      biLogger.log(E.keyboardShortcutAction, {
        button_name: buttonName,
        category: undefined,
        origin: undefined,
        pluginUniqueId: undefined,
        plugin_id: pluginId,
        plugins_details: undefined,
        type: undefined,
        value,
        version,
        content_id,
        settingSessionId: undefined,
      }),
    onMediaUploadStart: (correlationId, plugin_id, fileSize, mediaType, version, content_id) => {
      biLogger.log(E.uploadMediaTry, {
        plugin_id,
        correlationId,
        fileSize,
        mediaType,
        type: undefined,
        version,
        content_id,
      });
    },
    onMediaUploadEnd: (
      correlationId,
      plugin_id,
      duration,
      fileSize,
      mediaType,
      isSuccess,
      errorReason,
      version,
      content_id
    ) => {
      biLogger.log(E.uploadMediaFinished, {
        plugin_id,
        correlationId,
        duration,
        fileSize,
        mediaType,
        isSuccess,
        errorReason,
        type: undefined,
        version,
        content_id,
      });
    },
    onPluginAction: (eventName: keyof typeof onPluginActionMap, eventParams) => {
      if ((eventParams as any).params) {
        const params = JSON.stringify((eventParams as any).params);
        (eventParams as any).params = params;
      }
      const { contentId: content_id, ...rest } = eventParams || {};
      biLogger.log(onPluginActionMap[eventName], {
        content_id,
        version: undefined,
        plugins_details: undefined,
        ...rest,
      });
    },
    onPluginsPopOverTabSwitch: ({ pluginId, buttonName, version, contentId: content_id }) => {
      biLogger.log(E.pluginsPopoverTabSwitch, {
        plugin_id: pluginId,
        button_name: buttonName,
        content_id,
        version,
        plugins_details: undefined,
        pluginUniqueId: undefined,
        settingSessionId: undefined,
        category: undefined,
        origin: undefined,
        value: undefined,
        type: undefined,
      });
    },
    onPluginsPopOverClick: ({ pluginId, buttonName, version, contentId: content_id }) => {
      biLogger.log(E.pluginsPopoverClick, {
        plugin_id: pluginId,
        button_name: buttonName,
        content_id,
        version,
        plugins_details: undefined,
        pluginUniqueId: undefined,
        settingSessionId: undefined,
        category: undefined,
        origin: undefined,
        value: undefined,
        type: undefined,
      });
    },
    onChangePluginSettings: ({ pluginId, actionName, value, version, contentId: content_id }) => {
      biLogger.log(E.changePluginSettings, {
        plugin_id: pluginId,
        actionName,
        content_id,
        value,
        version,
        container: undefined,
        container_id: undefined,
        container_platform: undefined,
        entry_point: undefined,
        entry_type: undefined,
        layout: undefined,
        params: value,
        pluginUniqueId: undefined,
        plugins_details: undefined,
      });
    },
    mediaPluginsDetails: ({
      pluginId,
      creator,
      title,
      track_duration,
      url,
      type,
      version,
      contentId: content_id,
    }) => {
      biLogger.log(E.audioPluginDetails, {
        plugin_id: pluginId,
        creator,
        title,
        track_duration: track_duration?.toString(),
        url,
        type,
        version,
        content_id,
        pluginUniqueId: undefined,
        container: undefined,
        container_id: undefined,
        container_platform: undefined,
        params: undefined,
      });
    },
  };
};

// @TODO temporary workaround until migrating to catalog v2
type GUID = string;

type ModalActionParams = {
  post_id?: string;
  action?: string;
  container?: string;
  wixRicosVersion?: string;
  container_id?: string;
  container_platform?: string;
  version?: string;
  modal_session_id?: GUID;
  container_usage?: string;
  content_id?: string;
  uuid?: GUID;
  msid?: GUID;
  numActions?: number;
  actionNumber?: number;
  rce_session_id?: GUID;
  modal_id?: string;
  plugin_id?: string;
};
function modalAction(params: ModalActionParams) {
  return { evid: 59, src: 116, endpoint: '', params };
}

type AnyButtonClickParams = {
  element_id?: string;
  url?: string;
  elementGroup?: string;
  elementTitle?: string;
  actionName?: string;
  details?: string;
  elementType?: string;
  value?: string;
};

const analyticsAnyButtonClickAction = (params: AnyButtonClickParams) => {
  return { evid: 1113, src: 76, endpoint: '', params };
};

const buildAnyButtonClickActionParams = (
  contentId?: string,
  partialNode?: Omit<Node, 'nodes' | 'id' | 'style'>
): Required<AnyButtonClickParams> | undefined => {
  if (partialNode) {
    const commonParams = {
      element_id: contentId || '',
      url: typeof window !== 'undefined' ? window.location.href : '',
      elementGroup: 'Ricos',
      actionName: '',
    };

    switch (partialNode.type) {
      case Node_Type.BUTTON: {
        return {
          ...commonParams,
          elementTitle: partialNode.buttonData?.text || '',
          details: partialNode.buttonData?.link?.rel
            ? JSON.stringify(partialNode.buttonData.link.rel)
            : '',
          elementType: Node_Type.BUTTON,
          value: partialNode.buttonData?.link?.url || '',
        };
      }
      case Node_Type.LINK_PREVIEW: {
        return {
          ...commonParams,
          elementTitle: partialNode.linkPreviewData?.title || '',
          details: partialNode.linkPreviewData?.link?.rel
            ? JSON.stringify(partialNode.linkPreviewData.link.rel)
            : '',
          elementType: Node_Type.LINK_PREVIEW,
          value: partialNode.linkPreviewData?.link?.url || '',
        };
      }
      case Node_Type.APP_EMBED: {
        return {
          ...commonParams,
          elementTitle: partialNode.appEmbedData?.name || '',
          details: partialNode.appEmbedData?.type || '',
          elementType: Node_Type.APP_EMBED,
          value: partialNode.appEmbedData?.url || '',
        };
      }
      case Node_Type.TEXT: {
        const linkDecoration = partialNode.textData?.decorations?.find(
          ({ type }) => type === Decoration_Type.LINK
        ) as LinkDecoration;

        if (linkDecoration) {
          return {
            ...commonParams,
            elementTitle: partialNode.textData?.text || '',
            details: linkDecoration?.linkData?.link?.rel
              ? JSON.stringify(linkDecoration.linkData.link.rel)
              : '',
            elementType: Decoration_Type.LINK,
            value: linkDecoration?.linkData?.link?.url || '',
          };
        }
        break;
      }
      default: {
        return;
      }
    }
  }

  return;
};
